package com.google.javascript.jscomp.type;

import com.google.common.base.Preconditions;
import com.google.javascript.jscomp.CodingConvention;
import com.google.javascript.jscomp.type.JSType;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import com.google.javascript.rhino.jstype.EnumElementType;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeNative;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.ParameterizedType;
import com.google.javascript.rhino.jstype.StaticSlot;
import com.google.javascript.rhino.jstype.TemplateType;
import com.google.javascript.rhino.jstype.UnionType;
import com.google.javascript.rhino.jstype.Visitor;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.mockito.junit.MockitoJUnitRunner;
import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.*;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class RestrictByOneTypeOfResultVisitor_caseTopType_TriageGen1Test {

    @Mock
    private JSType mockTopType;

    @Mock
    private JSType mockNativeType;

    @Mock
    private JSType mockValue;

    private TestVisitor visitor;

    /**
     * Since the method is protected, we create a subclass to expose it for testing.
     */
    private static class TestVisitor extends ChainableReverseAbstractInterpreter.RestrictByOneTypeOfResultVisitor {
        private boolean resultEqualsValue;
        private JSType value;

        public TestVisitor(boolean resultEqualsValue, JSType value) {
            this.resultEqualsValue = resultEqualsValue;
            this.value = value;
        }

        // Expose the protected method for testing
        @Override
        JSType caseTopType(JSType topType) {
            return super.caseTopType(topType);
        }

        // Mocking the dependency method used in the logic
        @Override
        protected JSType getNativeTypeForTypeOf(JSType type) {
            return getNativeTypeForTypeOfInternal(type);
        }

        // Placeholder to be overridden by spy
        protected JSType getNativeTypeForTypeOfInternal(JSType type) {
            return null;
        }
    }

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
    }

    @Test
    public void testCaseTopType_resultEqualsValueFalse_returnsTopType() {
        // Arrange
        visitor = new TestVisitor(false, mockValue);
        TestVisitor spyVisitor = spy(visitor);

        // Act
        JSType result = spyVisitor.caseTopType(mockTopType);

        // Assert
        assertThat(result).isEqualTo(mockTopType);
    }

    @Test
    public void testCaseTopType_resultEqualsValueTrue_typeByNameIsNull_returnsTopType() {
        // Arrange
        visitor = new TestVisitor(true, mockValue);
        TestVisitor spyVisitor = spy(visitor);
        // Simulate getNativeTypeForTypeOf returning null
        doReturn(null).when(spyVisitor).getNativeTypeForTypeOfInternal(mockValue);

        // Act
        JSType result = spyVisitor.caseTopType(mockTopType);

        // Assert
        assertThat(result).isEqualTo(mockTopType);
    }

    @Test
    public void testCaseTopType_resultEqualsValueTrue_typeByNameIsNotNull_returnsTypeByName() {
        // Arrange
        visitor = new TestVisitor(true, mockValue);
        TestVisitor spyVisitor = spy(visitor);
        // Simulate getNativeTypeForTypeOf returning a valid JSType
        doReturn(mockNativeType).when(spyVisitor).getNativeTypeForTypeOfInternal(mockValue);

        // Act
        JSType result = spyVisitor.caseTopType(mockTopType);

        // Assert
        assertThat(result).isEqualTo(mockNativeType);
        assertThat(result).isNotEqualTo(mockTopType);
    }
}
